    { q: 'Гравитациялық тұрақтының мәні:', o: ['9,8 м/с²', '6,67·10⁻¹¹ Н·м²/кг²', '3·10⁸ м/с', '1,6·10⁻¹⁹ Кл'], a: 1, e: 'G = 6,67·10⁻¹¹ Н·м²/кг².' },
    { q: 'Ай Жерге неге құлап түспейді?', o: ['Айға тартылыс әсер етпейді', 'Ай орбиталық жылдамдықпен қозғалып, тартылыс оны орбитада ұстап тұрады', 'Айды Күн ұстап тұр', 'Ай Жерді тартады, ал Жер Айды тартпайды'], a: 1, e: 'Тартылыс күші центрге тартқыш күш рөлін атқарады – Ай Жерге үздіксіз «құлап», бірақ одан өтіп кетіп отырады.' },
    { q: 'KazSat-3-ке әсер ететін тартылыс күші орбитада Жер бетіндегіден шамамен неше есе аз?', o: ['2', '10', '44', '1000'], a: 2, e: '(42 157 / 6371)² ≈ 43,8.' }
