  obj: ['9.1.2.3 – көкжиекке бұрыш жасай және вертикаль лақтырылған дененің қозғалысы кезіндегі физикалық шамалардың өзгерісін сипаттау'], flow: [7, 30, 3, 5], img: 'img/comic-l05-b.jpg', comics: ['img/comic-l05-a.jpg', 'img/comic-l05-b.jpg'],
