  video: [{ t: 'Жаңа сабақ: бейнеролик', u: 'https://youtu.be/oKFqDmoJSoI' }],
  sims: [{ t: 'Горизонталь лақтыру', u: VAS('template.php?s=gp_vrh_vodorovny') }, { t: 'Қозғалыстарды қосу', u: VAS('templateimg.php?s=gp_skladani_pohybu') }, { t: 'PhET: Projectile Data Lab', u: 'https://phet.colorado.edu/en/simulations/projectile-data-lab' }],
